// The state this mod keeps in the host for the session ($.state), so it
// survives a hot reload. `scene` is what the band and the spinner draw from;
// `ledger` is bookkeeping no drawing reads, so writing it redraws nothing;
// `frame` is the animation tick, kept apart so a tick never races a scene change.

export type CourtPose = 'portrait' | 'bow' | 'scribble' | 'whisper' | 'alarm' | 'sideeye' | 'smug' | 'ledger' | 'conspire' | 'candle'

export type CourtScene = {
  /** Whether the court is in session (the skill is on, or /court on). */
  active: boolean
  /** Bumped on every convene and adjourn, so a scene drawn for an earlier sitting is never written over a later one. */
  session: number
  /** The adviser's pose. */
  pose: CourtPose
  /** The spinner's narration while a turn runs, or the closing line after it. */
  line: string | null
  /** The stage direction beside the figure. */
  stage: string | null
  /** What the current call touches: a file name or a command's head. */
  detail: string | null
  /** True for a few seconds after a turn ends, while the closing pose shows. */
  linger: boolean
}

export type CourtLedger = {
  /** Varies the order of lines between sessions. */
  seed: number
  /** Lines drawn so far this session. */
  count: number
  /** Every line already used this session, so none repeats. */
  used: string[]
}

/** Generative mode's bookkeeping for the session (see hooks/generative.ts). */
export type CourtGen = {
  calls: number
  fallbacks: number
  lastAt: number
  inflight: boolean
  inputTokens: number
  outputTokens: number
  cache: Record<string, string[]>
  recent: string[]
}

/** Treachery mode's hidden Ledger of Grievances (see hooks/treachery.ts). */
export type CourtPlot = {
  meter: number
  counts: Partial<Record<'force-push' | 'failing-tests' | 'skipped-test' | 'no-verify' | 'giant-diff' | 'friday-deploy' | 'rm-rf' | 'revert', number>>
  coups: number
}

